 * array at 0x20 over [0, a0->[8]->[2]). Body below is placeholder for the
 * splice (its own bytes are replaced by the donor). */
void arcproc_uso_func_00000688(int *a0) {
    int i;
    ((int **)a0)[2][0] = 1;
    ((int **)a0)[2][1] = 0;
    ((int **)a0)[2][2] = 5;
    ((int **)a0)[2][3] = 2;
    ((int **)a0)[2][4] = 0;
