typedef struct { int a, b, c; } Tri3i;
typedef struct { float x, y, z; } Vec3;
void arcproc_uso_func_000009CC(Vec3 *dst) {
    int pad_top[1];
    Tri3i raw;
    int pad_mid[2];
    Tri3i tmp;
    int pad_bot[2];
    gl_func_00000000(&D_00000000, &raw, 12);
    tmp = raw;
    dst->x = *(float*)&tmp.a;
    dst->y = *(float*)&tmp.b;
    dst->z = *(float*)&tmp.c;
}

#ifdef NON_MATCHING
/* arcproc_uso_func_00000A3C: 205 insns (0x334) — 4-stage allocator/initializer
 * constructor. Sibling of 0x880 family in arcproc_uso_tail1.c.
 *
 * 2026-06-01 (23.72 -> 27.62): confirmed member of the 0x6A8-alloc constructor
 * family (siblings: timproc_b3 994, timproc_b1 097C, titproc 1E9C). Ported the
 * proven 5-stage cascade (goto-chain dead-guards + distinct externs
 * D_arc_A3C_v0..3; self alloc 0x780, D-template 0x3B8 same as 994) + the early
 * field-init. arcproc takes a 5TH arg (a4 -> self->0x528; a3 -> self->0x6a8),
 * unlike the 4-arg siblings, and has a unique sub-loop tail. TBD: sub=gl(0xD8)
 * node + vtable-dispatch + the arcproc sub-loop (insns ~78-205 of /tmp/tarc.txt).
 *
 * ENTRY DECODE (0xA3C-0xB04, ~50 insns characterized 2026-05-04):
 *   - Frame: addiu sp,-0x40; saves s0/s1/ra at 0x1C/0x20/0x24; spills
 *     a1/a2/a3 at 0x44/0x48/0x4C (caller-preserved args).
 *   - Stage 1: if a0 == 0, alloc 0x780 → s1; else s1 = a0.
 *   - Stage 2: if s1 != 0, alloc 0x6A8 → s0 (linked under s1); on success
 *     stores &D_alloc_link at *(s0+0x28).
 *   - Stage 3: if s0 != 0, alloc 0x50 → spill@sp+0x38; on success calls
 *     gl_func(spilled, &D_arc_table_3B8) to init.
 *   - Stage 4: if (alloc_3 != 0), alloc 0x2C → another sub-obj; calls
 *     gl_func(sub_obj, &D_arc_table_3B8); writes &D_E to *(sub+0x28).
 *
 * KEY OFFSETS WRITTEN:
 *   - *(s1+0x28) = &D_arc_link_E       ; canonical "vtable/parent" slot
 *   - *(s0+0x28) = &D_arc_link_E
 *   - *(s0+0x568) = 0                   ; sub-obj clear
 *   - *(s0+0x6B8) = 0
 *   - *(s0+0x6A8), *(s0+0x6AC), *(s0+0x528) = sub-obj pointers (linked)
 *   - *(s0+0x77C) = lwc1 result (initial float, likely from alloc_3 init)
 *
 * REMAINING ~155 insns (0xB04-0xD6C): more sub-allocator stages, fan-out
 * stores, conditional sub-init via gl_func dispatch table at &D_arc_table_3D0,
 * final epilogue restoring s0/s1/ra and returning s1 in v0.
 *
 * This is a CONSTRUCTOR with cross-USO alloc dependency — multi-tick decomp.
 * Stub C body documents the 4-stage alloc skeleton for grep discoverability;
 * does NOT match (default INCLUDE_ASM build is correct).
 *
 * 2026-06-22 RESIDUAL CLASS = GLOBAL REGALLOC + FRAME-SIZE cap (not a bug):
 * fuzzy 64.57%. Full body decoded & control-flow verified against target
 * (expected/.../arcproc_uso_tail1.c.o @0x7fc). Logic is correct, but IDO
 * threads the primary object through a DIFFERENT s-register than target
 * (target: self=s1 / n1=s0, args spilled low @0x44/48/4c in prologue;
 * build: self=s0, args spilled high @0x5c/60/64) and the frame is 0x58 vs
 * target 0x40 (6-word gap). Normalized LCS (branch/jal offsets masked) is
 * only 73/205 = 35.6% — two-thirds of insns differ in opcode/register, so
 * this is whole-function coloring divergence, NOT a small permuter-bridgeable
 * residual. The frame-size delta alone is beyond permuter's local moves.
 * Matches the documented "correct-logic / divergent-regalloc on large fn" cap
 * class. All callees are jal-0 placeholders (no recoverable symbols). */
extern int gl_func_arc_alloc();
extern char D_arc_table_3B8[];
extern char D_arc_table_3D0[];
extern char D_arc_link_E;
extern char D_arc_A3C_v0;
extern char D_arc_A3C_v1;
extern char D_arc_A3C_v2;
extern char D_arc_A3C_v3;
extern char D_arc_A3C_v4;
void *arcproc_uso_func_00000A3C(int *arg0, int arg1, int arg2, int arg3, int arg4) {
    register int *node;   /* s0: sub-cascade + every registration node */
    int * volatile third; /* home 0x38(sp); REUSED for the 0xD8 sub-alloc */
    int *fourth;          /* home 0x34(sp) */
    int *rtemp;           /* 0x30(sp) phantom: v0-role temps */
    int * volatile slot;  /* home 0x2C(sp): def folded into first reg call */

    if (arg0 == 0) {
        arg0 = (int *)gl_func_00000000(0x780);
        if (arg0 == 0) goto done;
    }
    node = arg0;
    if (node == 0) {
        node = (int *)gl_func_00000000(0x6A8);
        if (node == 0) goto after_node;
    }
    third = node;
    if (node == 0) {
        if ((third = (int *)gl_func_00000000(0x50)) == 0) goto after_third;
    }
    fourth = third;
    if (fourth == 0) {
        fourth = (int *)gl_func_00000000(0x2C);
        if (fourth == 0) goto after_fourth;
    }
    gl_func_00000000(fourth, (char *)&D_00000000 + 0x3B8);
    fourth[0x28 / 4] = (int)&D_arc_A3C_v0;
after_fourth:
    third[0x28 / 4] = (int)&D_arc_A3C_v1;
after_third:
    node[0x28 / 4] = (int)&D_arc_A3C_v2;
    gl_func_00000000((char *)node + 0x50);
after_node:
    arg0[0x28 / 4] = (int)&D_arc_A3C_v3;
    arg0[0x568 / 4] = 0;
    gl_func_00000000(arg0, arg1, (char *)&D_00000000 + 0x3C0, arg2);
    arg0[0x528 / 4] = arg4;
    arg0[0x6B8 / 4] = 0;
    arg0[0x6A8 / 4] = arg3;
    gl_func_00000000(arg0);
    *(float *)&arg0[0x77C / 4] = 0.0f;
    gl_func_00000000((char *)&D_00000000 + 0x3D0, 0);
    gl_func_00000000(&D_00000000, 0);
    if ((fourth = (int *)(third = (int *)gl_func_00000000(0xD8))) != 0) {
        gl_func_00000000(fourth);
        third[0x28 / 4] = (int)&D_arc_A3C_v4;
    }
    arg0[0x6AC / 4] = (int)third;
    *(int **)((char *)&D_00000000 + 0x138) = third;
    node = (int *)arg0[0x6AC / 4];
    node[0xB4 / 4] = 7;
    gl_func_00000000(arg0[0x6AC / 4], arg0, arg0[0x568 / 4], arg0[0x6A8 / 4], arg0[0x528 / 4]);
    rtemp = (int *)arg0[0x6AC / 4];
    node = (int *)rtemp[0x28 / 4];
    ((void (*)(int))node[0x5C / 4])(*(short *)((char *)node + 0x58) + (int)rtemp);
    ((int *)((int *)arg0[0x6AC / 4])[0x44 / 4])[0x18 / 4] = *(int *)((char *)arg0[0x6A8 / 4] + 0x34);
    ((int *)((int *)arg0[0x6AC / 4])[0x44 / 4])[0x14 / 4] = *(int *)((char *)arg0[0x6A8 / 4] + 0x34);
    node = (int *)arg0[0x6AC / 4];
    gl_func_00000000(slot = (int *)((char *)arg0 + 0x10), node);
    if (node[0x14 / 4] != 0) {
        node[0x4 / 4] = 1;
    }
    node[0x14 / 4] = (int)arg0;
    gl_func_00000000(arg0, arg1);
    rtemp = (int *)gl_func_00000000(0);
    arg0[0x48 / 4] = (int)rtemp;
    gl_func_00000000(rtemp, arg0);
    node = (int *)&D_00000000;
    gl_func_00000000(arg0[0x48 / 4], (node[0] + 3) << 16, -1, &D_arc_table_3D0);
    gl_func_00000000(arg0[0x48 / 4], ((node[0] + 3) << 16) | 9, -1, &D_arc_table_3D0);
    gl_func_00000000(arg0[0x48 / 4], ((node[0] + 3) << 16) | 5, -1, &D_arc_table_3D0);
    *(int *)((char *)arg0[0x48 / 4] + 0x30) = arg0[0x568 / 4];
    gl_func_00000000(arg0[0x48 / 4]);
    gl_func_00000000(slot, node = (int *)arg0[0x48 / 4]);
    if (node[0x14 / 4] != 0) {
        node[0x4 / 4] = 1;
    }
    node[0x14 / 4] = (int)arg0;
    node = (int *)*(int *)((char *)&D_00000000 + 0x190);
    gl_func_00000000(slot, node);
    if (node[0x14 / 4] != 0) {
        node[0x4 / 4] = 1;
    }
    node[0x14 / 4] = (int)arg0;
    gl_func_00000000(*(int *)((char *)&D_00000000 + 0x190), 1, 0);
    gl_func_00000000();
    *(int *)((char *)&D_00000000 + 0x40) = 5;
